class Widget {};

// Deleters for demonstration
auto widgetFileDeleter = [](Widget* w) { /* log to file, then */ delete w; };
auto widgetNetworkDeleter = [](Widget* w) { /* send msg, then */ delete w; };

// With unique_ptr, the deleter is part of the type
std::unique_ptr<Widget, decltype(widgetFileDeleter)> 
    u_ptr1(new Widget(), widgetFileDeleter);

std::unique_ptr<Widget, decltype(widgetNetworkDeleter)> 
    u_ptr2(new Widget(), widgetNetworkDeleter);

// u_ptr1 = std::move(u_ptr2); // COMPILE ERROR: Incompatible types due to different deleters

// With shared_ptr, the deleter is not part of the type
std::shared_ptr<Widget> s_ptr1(new Widget(), widgetFileDeleter);
std::shared_ptr<Widget> s_ptr2(new Widget(), widgetNetworkDeleter);

// This is perfectly valid; both are of type std::shared_ptr<Widget>
s_ptr1 = s_ptr2; // OK: types are compatible. s_ptr1 now shares ownership with s_ptr2.
